@st.cache_data(ttl=86400, show_spinner=False)
def _canli_logo_src(sembol):
    """Canlı izleme tablosunda BIST şirket logosunu getirir; bulunamazsa None döner."""
    kod = re.sub(r"[^A-Z0-9]", "", str(sembol).upper())
    if not kod:
        return None
    try:
        import urllib.request
        url = (
            "https://cdn.jsdelivr.net/gh/ahmeterenodaci/"
            "Istanbul-Stock-Exchange--BIST--including-symbols-and-logos/"
            f"logos/{kod}.png"
        )
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 ARNI/1.0"})
        with urllib.request.urlopen(req, timeout=4) as r:
            raw = r.read()
        if raw and len(raw) > 100:
            return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
    except Exception:
        pass
    return None


def _canli_logo_html(sembol):
    kod = re.sub(r"[^A-Z0-9]", "", str(sembol).upper())
    src = _canli_logo_src(kod)
    if src:
        return f"<span class='live-stock-logo'><img src='{src}' alt='{kod}'></span>"
    return f"<span class='live-stock-dot'>{kod[:2]}</span>"


def _arni_canli_tablo():
    from datetime import datetime
    satirlar=[]
    for kod in live_selected:
        try:
            d=veri_getir(kod+".IS",10)
            if d is None or d.empty or "Close" not in d.columns:
                continue
            close=pd.to_numeric(d["Close"],errors="coerce").replace([np.inf,-np.inf],np.nan).dropna()
            if close.empty:
                continue
            son=float(close.iloc[-1])
            onceki=float(close.iloc[-2]) if len(close)>=2 else son
            deg=((son-onceki)/onceki)*100 if onceki else 0.0
            gun=d.iloc[-1]
            dusuk=float(gun.get("Low",son)) if pd.notna(gun.get("Low",son)) else son
            yuksek=float(gun.get("High",son)) if pd.notna(gun.get("High",son)) else son
            hacim=float(gun.get("Volume",0)) if pd.notna(gun.get("Volume",0)) else 0.0
            satirlar.append({
                "kod":kod,"son":son,"deg":deg,"dusuk":dusuk,"yuksek":yuksek,
                "hacim":int(hacim),"zaman":datetime.now().strftime("%H:%M:%S")
            })
        except Exception:
            continue

    if not satirlar:
        st.warning(T("Canlı fiyat verisi şu anda alınamadı.", "Live price data is currently unavailable."))
        return

    st.markdown("""<style>
    .arni-live-wrap{background:rgba(255,255,255,.80);border:1px solid #dce5f2;border-radius:15px;padding:10px 10px 4px;box-shadow:0 8px 24px rgba(30,64,175,.07);overflow-x:auto}
    .arni-live-table{width:100%;border-collapse:separate;border-spacing:0;min-width:1000px;font-size:14px;color:#1f2a44}
    .arni-live-table th{background:#f7faff;padding:13px 10px;text-align:left;font-size:14px;font-weight:800;border-right:1px solid #edf2f8;white-space:nowrap}
    .arni-live-table td{padding:9px 10px;border-top:1px solid #edf2f8;border-right:1px solid #f0f4f9;vertical-align:middle;font-weight:650;white-space:nowrap}
    .arni-live-table tr:hover td{background:#fbfdff}
    .live-stock{display:flex;align-items:center;gap:9px;font-weight:850}
    .live-stock-logo{width:34px;height:34px;display:inline-flex;align-items:center;justify-content:center;flex:0 0 34px}
    .live-stock-logo img{width:34px;height:34px;object-fit:contain;display:block}
    .live-stock-dot{width:34px;height:34px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:#17345e;color:#fff;font-size:12px;font-weight:900;flex:0 0 34px}
    .live-pill{display:inline-block;min-width:86px;text-align:center;padding:8px 10px;border-radius:9px;font-weight:850}
    .live-up{background:#dcf8eb;color:#07834f}.live-down{background:#ffe7e7;color:#df2020}
    .live-low{background:#e4f9ef;color:#087d50}.live-high{background:#fff0f0;color:#d92525}.live-time{background:#e8f3ff;color:#1764b5}
    .live-num{font-weight:800;color:#273451}.live-foot{display:flex;justify-content:space-between;gap:12px;color:#68758d;font-size:12px;margin:10px 2px 3px;flex-wrap:wrap}
    </style>""", unsafe_allow_html=True)

    rows=[]
    for x in satirlar:
        cls='live-up' if x['deg']>=0 else 'live-down'
        arrow='↑' if x['deg']>=0 else '↓'
        rows.append(f"""<tr>
        <td><div class='live-stock'>{_canli_logo_html(x['kod'])}{x['kod']}</div></td>
        <td><span class='live-num'>₺{x['son']:,.2f}</span></td>
        <td><span class='live-pill {cls}'>{arrow} {x['deg']:+.2f}%</span></td>
        <td><span class='live-pill live-low'>₺{x['dusuk']:,.2f}</span></td>
        <td><span class='live-pill live-high'>₺{x['yuksek']:,.2f}</span></td>
        <td><span class='live-num'>{x['hacim']:,}</span></td>
        <td><span class='live-pill live-time'>{x['zaman']}</span></td>
        </tr>""")

    table=f"""<div class='arni-live-wrap'><table class='arni-live-table'><thead><tr>
    <th>🏢 {T('Hisse','Stock')}</th><th>🪙 {T('Fiyat','Price')}</th><th>↕️ {T('Günlük %','Daily %')}</th>
    <th>⬆️ {T('Gün Düşük','Day Low')}</th><th>⬇️ {T('Gün Yüksek','Day High')}</th><th>📦 {T('Hacim','Volume')}</th><th>🕒 {T('Zaman','Time')}</th>
    </tr></thead><tbody>{''.join(rows)}</tbody></table>
    <div class='live-foot'><span>ℹ️ {T(f'Toplam {len(satirlar)} hisse canlı izleniyor.',f'{len(satirlar)} stocks are being watched live.')}</span><span>◷ {T('Son güncelleme','Last update')}: {satirlar[-1]['zaman']}</span></div></div>"""
    st.markdown(table, unsafe_allow_html=True)

# Yeni Streamlit sürümlerinde panel kendi kendine yenilenir.
if hasattr(st, "fragment"):
    _live_fragment = st.fragment(run_every=30)(_arni_canli_tablo)
