# Takip listesi hisse logoları — onaylanan görsel stile göre yerel gömülü logolar.
TAKIP_LOGO_B64 = {
    "ASTOR": "",
    "TUPRS": "",
    "THYAO": "",
    "SISE": "",
    "ISCTR": "",
}

@st.cache_data(ttl=86400, show_spinner=False)
def _takip_logo_src(sembol):
    """Takip listesine sonradan eklenen BIST hisselerinin logosunu otomatik getirir.
    Önce uygulamaya gömülü/onaylı logoyu kullanır; yoksa BIST logo CDN'inden indirir.
    Ağ veya logo sorunu olursa güvenli biçimde kısaltma rozeti gösterilir.
    """
    kod = re.sub(r"[^A-Z0-9]", "", str(sembol).upper())
    if not kod:
        return None
    # RUZYE: ALMAD kodu 02.04.2025 itibarıyla RUZYE oldu.
    # Yeni kod için eski CDN'de logo olmadığı için güncel şirket logosunu kullan.
    if kod == "RUZYE":
        return "https://storage.fintables.com/media/uploads/company-logos/ruzye_almad.jpg"
    b64 = TAKIP_LOGO_B64.get(kod)
    if b64:
        return f"data:image/png;base64,{b64}"
    try:
        import urllib.request
        url = (
            "https://cdn.jsdelivr.net/gh/ahmeterenodaci/"
            "Istanbul-Stock-Exchange--BIST--including-symbols-and-logos/"
            f"logos/{kod}.png"
        )
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 ARNI/1.0"})
        with urllib.request.urlopen(req, timeout=4) as r:
            raw = r.read()
        if raw and len(raw) > 100:
            return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
    except Exception:
        pass
    return None

def _takip_logo_html(sembol):
    kod = re.sub(r"[^A-Z0-9]", "", str(sembol).upper())
    src = _takip_logo_src(kod)
    if src:
        return f"<span class='arni-stock-logo'><img src='{src}' alt='{kod}'></span>"
    return f"<span class='arni-stock-dot'>{kod[:2]}</span>"

